type Session = record(plate: str, hours: int)

fn parking_fee(hours: int) -> dec = when hours
    0 -> 0.0
    < 2 -> 2.5
    < 4 -> 5.0
    < 8 -> 8.0
    else -> 8.0 + 1.5 * dec(hours - 8)

fn session_fee(session: Session) -> dec = parking_fee(session.hours)

fn total_session_fees(sessions: list<Session>) -> dec =
    sessions |> sum(s => session_fee(s))

